-- Original Stride presentation catalog. Idempotent seed, no deletion.
on conflict (id) do update set slug = excluded.slug, name = excluded.name, subtitle = excluded.subtitle, audience = excluded.audience, category = excluded.category, sport = excluded.sport, collection = excluded.collection, price_minor = excluded.price_minor, compare_at_minor = excluded.compare_at_minor, image = excluded.image, color = excluded.color, color_hex = excluded.color_hex, badge = excluded.badge, sizes = excluded.sizes, description = excluded.description, featured_rank = excluded.featured_rank, published_at = excluded.published_at, published = excluded.published;
